// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// Each player's bag: how many of each kind they keep ("Wood ×7, Stone ×3"). The Multiplayer Server decides what is
// in it and, unless the Inventory says otherwise, saves it with the player's data, so it is still there on their next
// visit. Players put what they carry in and take one kind back out into their hand through the Bag window
// (./inventoryHud); scripts add and spend items. The Inventory prefab registers itself; a creator script imports:
//
//   import { countOf, addItems, removeItems, onInventory } from './runtime/inventory'
//
// Kinds are plain words compared trimmed and case-insensitively, the same words carry and Work Stations use. A player
// is a wallet.
//
// Either side (a client sees every present player's bag, as the server last published it):
//   countOf(player, kind)     → number — how many of that kind the player has
//   bagOf(player)             → { kind, count }[] — the whole bag, in the order kinds first went in
//   roomFor(player, kind)     → number — how many more fit (Infinity when nothing limits it; 0 with no Inventory)
//   onInventory(fn)           → remover. fn(event) for every change: on the server as it happens, on each client when
//                               the server tells it. event = { type, player, kind, count }, type 'add' (a script put
//                               some in) | 'remove' (a script took some out) | 'store' (the player put what they held
//                               into the bag) | 'take' (the player took one out into their hand).
// Server only (inside if (isServer())):
//   addItems(player, kind, count = 1)    → number — how many went in (fewer, or 0, when the bag is full)
//   removeItems(player, kind, count = 1) → boolean — takes exactly that many, or nothing when they have fewer
//
// The bag lives in game.playerData under the key 'inventory': never write that key yourself.
// Wire names: game.state.inventory, the game request 'inventory.act' and the broadcast 'inventory.event'.
import { PlayerIdentityData, engine } from '@dcl/sdk/ecs'
import { isServer } from '@dcl/sdk/network'
import { game, reportProblem, type Player } from './game'
import { giveItem, heldBy, takeItem } from './carry'
import {
  INVENTORY_EVENT_TYPES,
  addToBag,
  countIn,
  normalLimits,
  readBag,
  readBags,
  removeFromBag,
  roomFor as bagRoom,
  type Bag,
  type BagLimits,
  type InventoryEvent,
  type InventoryEventType
} from './pure/inventoryRules'

export type { Bag, InventoryEvent, InventoryEventType }

export interface InventorySpec {
  slots: number
  stackSize: number
  accepts: string
  keepBetweenVisits: boolean
  emptyEachRound: boolean
  fullText: string
  handsFullText: string
  emptyHandsText: string
}

export type InventoryAct = { type: 'store' } | { type: 'take'; kind: string }

interface InventoryHub {
  spec: InventorySpec | null
  limits: BagLimits
  side: 'server' | 'client' | null
  bags: Map<string, Bag>
  view: Record<string, Bag>
  listeners: Set<(event: InventoryEvent) => void>
}

const KEY = '__dclInventory_v1'
const STATE_KEY = 'inventory'
const DATA_KEY = 'inventory'
const REQUEST = 'inventory.act'
const EVENT = 'inventory.event'

function isHub(value: unknown): value is InventoryHub {
  return typeof value === 'object' && value !== null && 'bags' in value && value.bags instanceof Map &&
    'listeners' in value && 'limits' in value && 'view' in value
}

function hub(): InventoryHub {
  const globals = globalThis as unknown as Record<string, unknown>
  const current = globals[KEY]
  if (isHub(current)) return current
  const created: InventoryHub = {
    spec: null, limits: normalLimits(0, 0, ''), side: null, bags: new Map(), view: {}, listeners: new Set()
  }
  globals[KEY] = created
  return created
}

const key = (player: Player): string => player.toLowerCase()

/** The local player's wallet, '' before it is known. */
export function myWallet(): string {
  return PlayerIdentityData.getOrNull(engine.PlayerEntity)?.address.toLowerCase() ?? ''
}

// ---------------------------------------------------------------- registration

/** Called by the Inventory prefab from start(), on both sides. */
export function registerInventory(spec: InventorySpec): boolean {
  const h = hub()
  if (h.spec !== null) {
    reportProblem('Inventory', 'There are two Inventories in this scene. Keep one: every player has one bag.')
    return false
  }
  h.spec = spec
  h.limits = normalLimits(spec.slots, spec.stackSize, spec.accepts)
  if (isServer()) {
    h.side = 'server'
    startServer(h)
  } else {
    h.side = 'client'
    startClient(h)
  }
  return true
}

// ---------------------------------------------------------------- reads (either side)

function bagIn(h: InventoryHub, player: Player): Bag {
  return h.side === 'server' ? h.bags.get(key(player)) ?? [] : h.view[key(player)] ?? []
}

export function bagOf(player: Player): Bag {
  return bagIn(hub(), player).map((entry) => ({ ...entry }))
}

export function countOf(player: Player, kind: string): number {
  return countIn(bagIn(hub(), player), kind)
}

export function roomFor(player: Player, kind: string): number {
  const h = hub()
  if (h.spec === null) return 0
  return bagRoom(bagIn(h, player), kind, h.limits)
}

export function onInventory(fn: (event: InventoryEvent) => void): () => void {
  const h = hub()
  h.listeners.add(fn)
  return () => { h.listeners.delete(fn) }
}

function tell(h: InventoryHub, event: InventoryEvent): void {
  for (const listener of [...h.listeners]) {
    try {
      listener(event)
    } catch (e) {
      console.error(`[inventory] an onInventory listener failed on "${event.type}":`, e)
    }
  }
}

// ---------------------------------------------------------------- server

function serverHub(verb: string): InventoryHub | null {
  const h = hub()
  if (!isServer()) {
    console.error(`[you] ${verb} only runs on the server. Put this line inside if (isServer()).`)
    return null
  }
  if (h.spec === null) {
    console.error(`[you] ${verb} needs an Inventory in the scene: place the Inventory prefab first.`)
    return null
  }
  return h
}

function publish(h: InventoryHub): void {
  game.setState({ [STATE_KEY]: Object.fromEntries(h.bags) })
}

function loadBag(h: InventoryHub, player: Player): Bag {
  const known = h.bags.get(key(player))
  if (known !== undefined) return known
  const saved = h.spec?.keepBetweenVisits === true ? readBag(game.playerData(player).get()[DATA_KEY]) : []
  h.bags.set(key(player), saved)
  return saved
}

function storeBag(h: InventoryHub, player: Player, bag: Bag): void {
  h.bags.set(key(player), bag)
  if (h.spec?.keepBetweenVisits === true) game.playerData(player).set({ [DATA_KEY]: bag })
  publish(h)
}

function emit(h: InventoryHub, event: InventoryEvent): void {
  tell(h, event)
  game.broadcast(EVENT, event)
}

export function addItems(player: Player, kind: string, count = 1): number {
  const h = serverHub('addItems')
  if (h === null) return 0
  const result = addToBag(loadBag(h, player), kind, count, h.limits)
  if (result.added === 0) return 0
  storeBag(h, player, result.bag)
  emit(h, { type: 'add', player: key(player), kind: kind.trim(), count: result.added })
  return result.added
}

export function removeItems(player: Player, kind: string, count = 1): boolean {
  const h = serverHub('removeItems')
  if (h === null) return false
  const next = removeFromBag(loadBag(h, player), kind, count)
  if (next === null) return false
  storeBag(h, player, next)
  emit(h, { type: 'remove', player: key(player), kind: kind.trim(), count: Math.floor(count) })
  return true
}

function readAct(data: unknown): InventoryAct | null {
  if (typeof data !== 'object' || data === null) return null
  const raw = data as Record<string, unknown>
  if (raw.type === 'store') return { type: 'store' }
  if (raw.type === 'take' && typeof raw.kind === 'string' && raw.kind.trim() !== '') return { type: 'take', kind: raw.kind.trim() }
  return null
}

function serverAct(h: InventoryHub, data: unknown, player: Player): { ok: boolean; message?: string } {
  const act = readAct(data)
  const spec = h.spec
  if (act === null || spec === null) return { ok: false }
  const bag = loadBag(h, player)
  if (act.type === 'store') {
    const held = heldBy(player)
    if (held === null) return { ok: false, message: spec.emptyHandsText }
    if (bagRoom(bag, held.kind, h.limits) < 1) return { ok: false, message: spec.fullText }
    const kind = takeItem(player)
    if (kind === null) return { ok: false }
    storeBag(h, player, addToBag(bag, kind, 1, h.limits).bag)
    emit(h, { type: 'store', player: key(player), kind, count: 1 })
    return { ok: true }
  }
  if (heldBy(player) !== null) return { ok: false, message: spec.handsFullText }
  const kind = bag.find((entry) => countIn([entry], act.kind) > 0)?.kind
  const next = kind === undefined ? null : removeFromBag(bag, kind, 1)
  if (kind === undefined || next === null) return { ok: false }
  if (!giveItem(player, kind)) return { ok: false, message: spec.handsFullText }
  storeBag(h, player, next)
  emit(h, { type: 'take', player: key(player), kind, count: 1 })
  return { ok: true }
}

function startServer(h: InventoryHub): void {
  game.onReady(() => publish(h))
  game.onPlayerJoin((player) => {
    loadBag(h, player)
    publish(h)
  })
  game.onPlayerLeave((player) => {
    h.bags.delete(key(player))
    publish(h)
  })
  game.onRoundStart(() => {
    if (h.spec?.emptyEachRound !== true) return
    for (const player of [...h.bags.keys()]) storeBag(h, player, [])
  })
  game.onRequest(REQUEST, (data: unknown, player) => serverAct(h, data, player))
}

// ---------------------------------------------------------------- client

function readEvent(data: unknown): InventoryEvent | null {
  if (typeof data !== 'object' || data === null) return null
  const raw = data as Record<string, unknown>
  if (!INVENTORY_EVENT_TYPES.includes(raw.type as InventoryEventType) || typeof raw.player !== 'string' ||
    typeof raw.kind !== 'string' || typeof raw.count !== 'number') return null
  return { type: raw.type as InventoryEventType, player: raw.player, kind: raw.kind, count: raw.count }
}

function replyOk(reply: unknown): { ok: boolean; message: string } {
  if (typeof reply !== 'object' || reply === null) return { ok: false, message: '' }
  const raw = reply as Record<string, unknown>
  return { ok: raw.ok === true, message: typeof raw.message === 'string' ? raw.message : '' }
}

/** Client: asks the server to put what the player holds into the bag, or one `kind` from it into their hand. */
export function askInventory(act: InventoryAct): Promise<{ ok: boolean; message: string }> {
  return game.request<unknown>(REQUEST, act).then(replyOk, (error: unknown) => {
    console.log(`[inventory] ${act.type} failed: ${String(error)}`)
    return { ok: false, message: 'No answer from the server. Try again.' }
  })
}

function startClient(h: InventoryHub): void {
  game.onBroadcast(EVENT, (data: unknown) => {
    const event = readEvent(data)
    if (event !== null) tell(h, event)
  })
  engine.addSystem(() => { h.view = readBags(game.state[STATE_KEY]) }, undefined, 'runtime-inventory')
}
